# owner: platform
import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def make_student(last, first):
    return Student("id-" + last, last, first, "A")

class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.roster = [
            make_student("Halloway", "Juno"),
            make_student("Dunmere", "Piet"),
            make_student("Alder", "Wren")
        ]

    def test_sorted_and_split_into_rows(self):
        self.assertEqual(
            seating_rows(self.roster, 2),
            [
                "Row 1: Alder, Wren | Dunmere, Piet",
                "Row 2: Halloway, Juno"
            ]
        )

    def test_single_row(self):
        lines = seating_rows(self.roster, 10)
        self.assertEqual(len(lines), 1)

    def test_same_last_name_uses_first_name(self):
        roster = [
            make_student("Reyes", "Zoe"),
            make_student("Reyes", "Abel")
        ]
        self.assertEqual(
            seating_rows(roster, 2),
            ["Row 1: Reyes, Abel | Reyes, Zoe"]
        )

    def test_bad_seat_counts(self):
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seating_rows(self.roster, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seating_rows([], 3)

if __name__ == "__main__":
    unittest.main()
